def f(N: int, M: int, pairs: List[Tuple[int, int]]) -> int:
    result = [[float('inf')]*N for _ in range(N)]
    for s, t in pairs:
        result[s][t] = result[t][s] = 1
    for k in range(N):
        for i in range(N):
            for j in range(N):
                result[i][j] = min(result[i][j], result[i][k]+result[k][j])
    max_val = float('-inf')
    for i in range(N):
        for j in range(N):
            max_val = max(max_val, result[i][j])
    return max_val
